const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hotelDeVille = ee.Geometry.Point([2.352, 48.856]);
  const faussesReposes = ee.Geometry.Point([2.175, 48.815]);
  const targetDate = '2024-08-06';

  // 2. Data Acquisition - Try MODIS Aqua (MYD11A1) for daytime LST around 1:30 PM local
  let aquaCol = ee.ImageCollection('MODIS/061/MYD11A1')
    .filterDate(targetDate, '2024-08-07')
    .select('LST_Day_1km', 'QC_Day');

  let aquaSize = await aquaCol.size().getInfo();
  console.log(`MODIS Aqua images on ${targetDate}: ${aquaSize}`);

  // Fallback to Terra if Aqua has no data
  if (aquaSize === 0) {
    console.log('Trying MODIS Terra (MOD11A1)...');
    aquaCol = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(targetDate, '2024-08-07')
      .select('LST_Day_1km', 'QC_Day');
    aquaSize = await aquaCol.size().getInfo();
    console.log(`MODIS Terra images on ${targetDate}: ${aquaSize}`);
  }

  if (aquaSize === 0) {
    console.log('No MODIS data available for this date.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get LST image and apply QC filter
  const lstImg = aquaCol.first();

  // QC filter: keep only good quality pixels (bits 0-1 = 00)
  const qcMask = lstImg.select('QC_Day').bitwiseAnd(3).eq(0);
  const lstMasked = lstImg.select('LST_Day_1km').updateMask(qcMask).multiply(0.02).subtract(273.15);

  // 4. Extract LST values at both locations
  const hotelStats = await lstMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hotelDeVille,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const forestStats = await lstMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: faussesReposes,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const hotelLST = hotelStats.LST_Day_1km;
  const forestLST = forestStats.LST_Day_1km;

  console.log(`Hotel de Ville LST: ${hotelLST !== null ? hotelLST.toFixed(2) + '°C' : 'null'}`);
  console.log(`Fausses-Reposes Forest LST: ${forestLST !== null ? forestLST.toFixed(2) + '°C' : 'null'}`);

  // 5. Validation & Final Answer
  if (hotelLST === null || forestLST === null) {
    console.log('No valid pixels at one or both locations.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (hotelLST < -50 || hotelLST > 70 || forestLST < -50 || forestLST > 70) {
    console.log('Invalid LST values detected.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (hotelLST < forestLST) {
    console.log('Hotel de Ville was cooler than Fausses-Reposes forest.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Hotel de Ville was NOT cooler than Fausses-Reposes forest.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
